var mySize, angle;
var seed = Math.random() * 2965;
var color1;

let colors4 = "8c75ff-c553d2-2dfd60-2788f5-23054f".split("-").map((a) => "#" + a);
let colors5 = "f21252-8834f1-c4dd92-184fd3-f9fee2".split("-").map((a) => "#" + a);
let colors6 = "2E294E-541388-F1E9DA-FFD400-D90368".split("-").map((a) => "#" + a);
let colors7 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a);
let colors8 = "e9baaa-ffa07a-164555-ffe1d0-acd9e7".split("-").map((a) => "#" + a);
let colorbg = "ffffff".split("-").map((a) => "#" + a);
let colorbg2 = "ffffff01".split("-").map((a) => "#" + a);
var t, timer;
var color_setup;

function setup() {
	randomSeed(seed);
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize);
	t = timer = 0;
	color_setup = random([colors4, colors5, colors6, colors7, colors8]);
	angle = 0;
	background(random(color_setup));

}

function draw() {
	randomSeed(seed);
	noFill();
	let plus = random(mySize*0.8, mySize*0.6);
	for (let k = 0; k < int(random(10,20)); k++) {
		strokeCap(SQUARE);
		drawingContext.shadowColor = random(color_setup);
		drawingContext.shadowOffsetX = random(-2,2);
		drawingContext.shadowOffsetY = random(-2,2);
		drawingContext.shadowBlur = 0;
		push();
		translate(width / 2, height / 2);
		rotate(random([PI / 2, PI, -PI / 2, -PI]) * k + angle);
		let a = random(2, 5)
		strokeWeight(random(1));
		stroke(random(color_setup));
		line(0, 0, plus / a, random(plus / a, plus / a / 2));
		strokeWeight(random(0.25));
		stroke(str(random(color_setup))+"1a");
		circle(0, 0, random(plus / a, plus / a / 2));
		pop();
	}
	if (angle < TAU/2) {
		angle += TAU / 360/random([5,8,2,1]);
	} else {
		noLoop();
	}
}

function keyPressed() {
	//noLoop();
	saveCanvas("0216_2_untitled_2022", "png");
}

